public struct FfiAnswerResult {
    public var answer: String
    public var selectedMemory: FfiMemoryRecord?
    public var confidence: Float
    public var rerankerUsed: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(answer: String, selectedMemory: FfiMemoryRecord?, confidence: Float, rerankerUsed: String) {
        self.answer = answer
        self.selectedMemory = selectedMemory
        self.confidence = confidence
        self.rerankerUsed = rerankerUsed
    }
}



extension FfiAnswerResult: Equatable, Hashable {
    public static func ==(lhs: FfiAnswerResult, rhs: FfiAnswerResult) -> Bool {
        if lhs.answer != rhs.answer {
            return false
        }
        if lhs.selectedMemory != rhs.selectedMemory {
            return false
        }
        if lhs.confidence != rhs.confidence {
            return false
        }
        if lhs.rerankerUsed != rhs.rerankerUsed {
            return false
        }
        return true
    }

